category":"favorite","region":"Indian","incomplete":false},{"id":"vegan-03","title":"Vegan Lentil & Kale Soup","baseServings":null,"ingredients":[{"name":"olive oil","quantity":2.0,"unit":"tbsp","preparation":"","originalText":"2 tbsp"},{"name":"yellow onion","quantity":1.0,"unit":"count","preparation":"","originalText":"1"},{"name":"carrots","quantity":4.0,"unit":"count","preparation":"","originalText":"4"},{"name":"celery stalks","quantity":2.0,"unit":"count","preparation":"","originalText":"2"},{"name":"kale","quantity":null,"unit":"text","preparation":"","originalText":"6 small or 3 large leaves"},{"name":"ground cumin","quantity":null,"unit":"text","preparation":"","originalText":"heaping 1/2 tsp"},{"name":"sea salt","quantity":1.5,"unit":"tsp","preparation":"","originalText":"1.5 tsp"},{"name":"black pepper","quantity":null,"unit":"text","preparation":"","originalText":"to taste"},{"name":"garlic","quantity":4.0,"unit":"clove","preparation":"","originalText":"4 cloves"},{"name":"fire-roasted diced tomatoes","quantity":null,"unit":"text","preparation":"","originalText":"1 can (14 oz)"},{"name":"dry green lentils","quantity":0.75,"unit":"cup","preparation":"","originalText":"3/4 cup"},{"name":"white wine vinegar","quantity":2.0,"unit":"tbsp","preparation":"","originalText":"2 tbsp"},{"name":"fresh thyme","quantity":12.0,"unit":"sprigs","preparation":"","originalText":"12 sprigs"},{"name":"vegetable broth","quantity":6.0,"unit":"cup","preparation":"","originalText":"6 cups"},{"name":"fresh parsley","quantity":0.5,"unit":"cup","preparation":"","originalText":"1/2 cup"},{"name":"red pepper flakes","quantity":null,"unit":"text","preparation":"","originalText":"to taste"}],"instructions":"Open the source recipe for cooking directions. Serves 4–6; source serving range is unconfirmed for scaling. Vegan version omits the optional Parmesan topping.","sourceUrl":"https://www.loveandlemons.com/lentil-soup/","category":"favorite","region":"International","incomplete":false}